package com.x.cloudnext.server.migration;

import java.util.LinkedHashMap;import java.util.Map;
import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import org.springframework.web.server.ResponseStatusException;
import com.x.cloudnext.server.auth.repository.AuthSessionRepository;import com.x.cloudnext.server.auth.repository.SsoBootstrapRepository;import com.x.cloudnext.server.config.CloudNextProperties;import com.x.cloudnext.server.form.MigrationManagementService;import com.x.cloudnext.server.form.MigrationValidationResponse;import com.x.cloudnext.server.migration.repository.LegacyArchiveMigrationTaskRepository;
import com.x.cloudnext.server.migration.repository.CloudNextMetaRepository;import com.x.cloudnext.server.migration.entity.CloudNextMeta;import java.time.Instant;
import com.x.cloudnext.server.migration.entity.LegacyArchiveMigrationTask;
import com.x.cloudnext.server.form.repository.DirectorySyncStateRepository;import com.x.cloudnext.server.form.FormDirectoryApplyService;

@Service
public class CutoverService {
 private final CloudNextProperties properties;private final MigrationManagementService migration;private final LegacyArchiveMigrationTaskRepository tasks;private final AuthSessionRepository sessions;private final SsoBootstrapRepository bootstraps;private final CloudNextMetaRepository meta;private final MigrationInventoryService inventory;private final DirectorySyncStateRepository directoryStates;
 public CutoverService(CloudNextProperties properties,MigrationManagementService migration,LegacyArchiveMigrationTaskRepository tasks,AuthSessionRepository sessions,SsoBootstrapRepository bootstraps,CloudNextMetaRepository meta,MigrationInventoryService inventory,DirectorySyncStateRepository directoryStates){this.properties=properties;this.migration=migration;this.tasks=tasks;this.sessions=sessions;this.bootstraps=bootstraps;this.meta=meta;this.inventory=inventory;this.directoryStates=directoryStates;}
 public Map<String,Object> status(){MigrationValidationResponse validation=migration.validateMigration();String version=properties.getCutover().getMigrationVersion();LegacyArchiveMigrationTask task=StringUtils.hasText(version)?tasks.findById(version).orElse(null):null;com.x.cloudnext.server.form.entity.DirectorySyncState directory=directoryStates.findById(FormDirectoryApplyService.SOURCE_KEY).orElse(null);boolean finalVerified=task!=null&&"VERIFIED".equals(task.getStatus());boolean providerReady="FORM".equalsIgnoreCase(properties.getAuth().getEffectiveProvider());boolean directoryFenceMatches=matchesDirectoryFence(task,directory);boolean inventoryReady=false;if(task!=null){try{inventory.assertMatches(task.getInventoryJson());inventoryReady=true;}catch(Exception ignored){inventoryReady=false;}}Map<String,Object> r=new LinkedHashMap<>();r.put("maintenanceMode",properties.getCutover().isMaintenanceMode());r.put("migrationVersion",version);r.put("migrationChecksum",task==null?"":task.getChecksum());r.put("migrationStatus",task==null?"MISSING":task.getStatus());r.put("validationReady",validation.isReady());r.put("providerReady",providerReady);r.put("formSnapshotEtag",directory==null?"":directory.getEtag());r.put("formSnapshotGeneration",directory==null?0L:directory.getLastSuccessGeneration());r.put("directoryFenceMatches",directoryFenceMatches);r.put("etagMatches",directoryFenceMatches);r.put("inventoryReady",inventoryReady);r.put("readyToClearSessions",properties.getCutover().isMaintenanceMode()&&validation.isReady()&&finalVerified&&providerReady&&directoryFenceMatches&&inventoryReady);r.put("blockers",validation.getBlockers());return r;}
 @Transactional public Map<String,Long> clearSessions(){if(!properties.getCutover().isMaintenanceMode())throw new ResponseStatusException(HttpStatus.CONFLICT,"cutover maintenance mode is not enabled");if(!"FORM".equalsIgnoreCase(properties.getAuth().getEffectiveProvider()))throw new ResponseStatusException(HttpStatus.CONFLICT,"authentication provider must be FORM before cutover");String version=properties.getCutover().getMigrationVersion();if(!StringUtils.hasText(version))throw new ResponseStatusException(HttpStatus.CONFLICT,"CLOUDNEXT_CUTOVER_MIGRATION_VERSION is required");com.x.cloudnext.server.form.entity.DirectorySyncState directory=directoryStates.findForUpdate(FormDirectoryApplyService.SOURCE_KEY).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Form directory state is missing"));LegacyArchiveMigrationTask task=tasks.findForUpdate(version).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"configured final legacy archive migration task does not exist"));if(!"VERIFIED".equals(task.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"configured final legacy archive migration task is not VERIFIED");if(!matchesDirectoryFence(task,directory))throw new ResponseStatusException(HttpStatus.CONFLICT,"Form directory generation changed or the final synchronization did not succeed");try{inventory.assertMatches(task.getInventoryJson());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}MigrationValidationResponse validation=migration.validateMigration();if(!validation.isReady())throw new ResponseStatusException(HttpStatus.CONFLICT,"cutover validation has blockers");long sessionCount=sessions.count();long bootstrapCount=bootstraps.count();long epoch=Instant.now().toEpochMilli();CloudNextMeta marker=meta.findById("onlyoffice_ticket_not_before_epoch_ms").orElseGet(CloudNextMeta::new);marker.setMetaKey("onlyoffice_ticket_not_before_epoch_ms");marker.setMetaValue(String.valueOf(epoch));meta.save(marker);CloudNextMeta versionMarker=meta.findById("cutover_migration_version").orElseGet(CloudNextMeta::new);versionMarker.setMetaKey("cutover_migration_version");versionMarker.setMetaValue(task.getVersion()+"|"+task.getChecksum()+"|"+directory.getEtag()+"|g="+directory.getLastSuccessGeneration());meta.save(versionMarker);bootstraps.deleteAllInBatch();sessions.deleteAllInBatch();Map<String,Long> result=new LinkedHashMap<>();result.put("deletedSessions",sessionCount);result.put("deletedSsoBootstraps",bootstrapCount);result.put("onlyofficeTicketNotBeforeEpochMs",epoch);return result;}
 private boolean matchesDirectoryFence(LegacyArchiveMigrationTask task,com.x.cloudnext.server.form.entity.DirectorySyncState directory){return task!=null&&directory!=null&&StringUtils.hasText(directory.getEtag())&&("SUCCESS".equals(directory.getLastOutcome())||"NOT_MODIFIED".equals(directory.getLastOutcome()))&&directory.getLastSuccessGeneration()>0L&&task.getFormSnapshotGeneration()==directory.getLastSuccessGeneration()&&directory.getEtag().equals(task.getFormSnapshotEtag())&&java.util.Objects.equals(directory.getLastSuccessAt(),task.getFormSnapshotSuccessAt())&&java.util.Objects.equals(directory.getLastSuccessCutoverVersion(),task.getVersion());}
}
